"use client";

import React, { useState } from "react";

interface FloatingFieldProps
  extends React.InputHTMLAttributes<HTMLInputElement> {
  label: string;
  error?: string;
  showPasswordToggle?: boolean;
  strengthDots?: number; // 0-3 for password strength
}

export default function FloatingField({
  label,
  error,
  showPasswordToggle = false,
  strengthDots,
  id,
  type = "text",
  className = "",
  ...props
}: FloatingFieldProps) {
  const [showPassword, setShowPassword] = useState(false);
  const inputType = showPasswordToggle
    ? showPassword
      ? "text"
      : "password"
    : type;

  return (
    <div className={`relative mb-[22px] ${error ? "error" : ""} ${className}`}>
      <input
        id={id}
        type={inputType}
        placeholder=" "
        className={`w-full bg-transparent border-0 border-b-[0.5px] ${
          error ? "border-b-[var(--error)]" : "border-b-[var(--text-3)]"
        } font-[DM_Sans] text-sm text-[var(--text)] pt-[18px] pb-2 outline-none transition-[border-color] duration-250 focus:border-b-[var(--brown)] peer`}
        {...props}
      />
      <label
        htmlFor={id}
        className="absolute left-0 top-[18px] text-sm text-[var(--text-3)] pointer-events-none transition-all duration-200 tracking-[.005em] peer-focus:top-0 peer-focus:text-[11px] peer-focus:text-[var(--text-2)] peer-focus:font-[DM_Mono] peer-focus:tracking-[.06em] peer-focus:uppercase peer-[:not(:placeholder-shown)]:top-0 peer-[:not(:placeholder-shown)]:text-[11px] peer-[:not(:placeholder-shown)]:text-[var(--text-2)] peer-[:not(:placeholder-shown)]:font-[DM_Mono] peer-[:not(:placeholder-shown)]:tracking-[.06em] peer-[:not(:placeholder-shown)]:uppercase"
      >
        {label}
      </label>

      {showPasswordToggle && (
        <button
          type="button"
          onClick={() => setShowPassword(!showPassword)}
          className="absolute right-0 top-[18px] bg-transparent border-none cursor-pointer p-1 transition-colors duration-150 hover:text-[var(--brown)]"
          style={{ color: showPassword ? "var(--brown)" : "var(--text-3)" }}
          aria-label="Show password"
        >
          <svg
            width="18"
            height="18"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.4"
          >
            <path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z" />
            <circle cx="12" cy="12" r="3" />
          </svg>
        </button>
      )}

      {strengthDots !== undefined && (
        <div className="flex gap-[5px] mt-2">
          {[0, 1, 2].map((i) => (
            <i
              key={i}
              className={`h-[3px] flex-1 rounded-sm transition-colors duration-250 ${
                i < strengthDots
                  ? "bg-[var(--brown)]"
                  : "bg-[rgba(26,23,20,.08)]"
              }`}
            />
          ))}
        </div>
      )}

      {error && (
        <div className="font-[DM_Mono] text-[11px] text-[var(--error)] mt-[6px] tracking-[.04em]">
          {error}
        </div>
      )}
    </div>
  );
}
